package vn.vinhkhang.warehouse;
import java.util.*;import java.io.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;import org.apache.poi.ss.util.CellRangeAddress;
@RestController @RequestMapping("/api/exports") public class ExcelExports {
 private final Api core;private final JdbcTemplate db;public ExcelExports(Api core,JdbcTemplate db){this.core=core;this.db=db;}
 static final Map<String,String> NAMES=Map.ofEntries(Map.entry("parts","Linh kiện"),Map.entry("suppliers","Nhà cung cấp"),Map.entry("stock","Tồn linh kiện"),Map.entry("models","Mẫu xe"),Map.entry("documents","Nhập xuất linh kiện"),Map.entry("bom","Định mức"),Map.entry("production","Lệnh sản xuất"),Map.entry("vehicles","Xe máy điện thành phẩm"),Map.entry("receipts","Phiếu nhập xe"),Map.entry("shipments","Phiếu xuất hàng"),Map.entry("reports","Báo cáo tồn kho"),Map.entry("audit","Nhật ký"),Map.entry("users","Tài khoản"));
 static final Map<String,String> LABELS=Map.ofEntries(Map.entry("SHIPMENT_PURPOSE","Loại xuất hàng"),Map.entry("ACCOUNT_KIND","Loại tài khoản"),Map.entry("ID","ID"),Map.entry("CODE","Mã"),Map.entry("NAME","Tên"),Map.entry("MODEL","Mẫu xe"),Map.entry("COLOR","Màu"),Map.entry("FRAME_NUMBER","Số khung"),Map.entry("MOTOR_NUMBER","Số máy"),Map.entry("QUANTITY","Số lượng"),Map.entry("UNIT","Đơn vị"),Map.entry("MINIMUM","Tồn tối thiểu"),Map.entry("PHONE","Điện thoại"),Map.entry("ADDRESS","Địa chỉ"),Map.entry("STATUS","Trạng thái"),Map.entry("TYPE","Loại"),Map.entry("SOURCE","Nguồn nhập"),Map.entry("CUSTOMER","Khách hàng / đại lý"),Map.entry("NOTE","Ghi chú"),Map.entry("CREATED_AT","Ngày tạo"),Map.entry("POSTED_AT","Ngày ghi sổ"),Map.entry("RECEIVED","Tổng nhập"),Map.entry("ISSUED","Tổng xuất"),Map.entry("BALANCE","Tồn cuối"),Map.entry("USERNAME","Tên đăng nhập"),Map.entry("DISPLAY_NAME","Họ tên"),Map.entry("ROLE","Vai trò"),Map.entry("ACTION","Thao tác"),Map.entry("ACTOR","Người thao tác"),Map.entry("ENTITY","Đối tượng"),Map.entry("VERSION","Phiên bản"),Map.entry("UNIT_COST","Đơn giá"),Map.entry("PART_ID","ID linh kiện"),Map.entry("PART_CODE","Mã linh kiện"),Map.entry("PART_NAME","Tên linh kiện"),Map.entry("DOCUMENT_ID","ID phiếu"),Map.entry("BOM_ID","ID định mức"),Map.entry("ORDER_ID","ID lệnh sản xuất"),Map.entry("RECEIPT_ID","ID phiếu nhập xe"),Map.entry("RECEIPT_CODE","Mã phiếu nhập xe"),Map.entry("SHIPMENT_CODE","Mã phiếu xuất hàng"),Map.entry("MODEL_ID","ID mẫu xe"),Map.entry("LOCATION_ID","ID kho"),Map.entry("SUPPLIER_ID","ID nhà cung cấp"),Map.entry("SUPPLIER","Nhà cung cấp"),Map.entry("CREATED_BY","ID người tạo"),Map.entry("COMPLETED_AT","Ngày hoàn thành"),Map.entry("USER_ID","ID người dùng"),Map.entry("ENTITY_ID","ID đối tượng"),Map.entry("DETAILS","Chi tiết"),Map.entry("USER_NOTE","Ghi chú bổ sung"),Map.entry("COMPONENTS","Số linh kiện"),Map.entry("VEHICLE_TYPE","Dòng xe"),Map.entry("ACTIVE","Hoạt động"),Map.entry("SHIPMENT_DATE","Ngày xuất"),Map.entry("REASON","Lý do xuất kho"),Map.entry("ACCESSORIES","Phụ kiện"),Map.entry("DELIVERY_PERSON","Người giao hàng"),Map.entry("RECIPIENT","Người nhận hàng"),Map.entry("WAREHOUSE_KEEPER","Thủ kho"),Map.entry("REQUESTED_QUANTITY","Số lượng yêu cầu"),Map.entry("ACTUAL_QUANTITY","Thực xuất"),Map.entry("UNIT_PRICE","Đơn giá"),Map.entry("AMOUNT","Thành tiền"),Map.entry("ITEM_CODE","Mã VTHH"),Map.entry("DESCRIPTION","Tên / quy cách"));
 void sheet(XSSFWorkbook book,String name,List<Map<String,Object>> rows){var sh=book.createSheet(name);var style=book.createCellStyle();var font=book.createFont();font.setBold(true);font.setColor(IndexedColors.WHITE.getIndex());style.setFont(font);style.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());style.setFillPattern(FillPatternType.SOLID_FOREGROUND);Set<String> hidden=Set.of("BOM_MODELS","COLOR_MODELS","COLOR_PARENT_ID","COLOR_MODEL_ID","COLOR_KEY","BOM_PART_ID","MINIMUM","PASSWORD_HASH","CODE_HASH","BEFORE_DATA","AFTER_DATA","DELETED","ARCHIVED");var keys=rows.isEmpty()?List.of("Ghi chú"):rows.getFirst().keySet().stream().filter(k->!hidden.contains(k)).toList();var header=sh.createRow(0);for(int i=0;i<keys.size();i++){var c=header.createCell(i);c.setCellValue(LABELS.getOrDefault(keys.get(i),keys.get(i)));c.setCellStyle(style);sh.setColumnWidth(i,Math.min(45,Math.max(16,c.getStringCellValue().length()+4))*256);}int index=1;for(var r:rows){var row=sh.createRow(index++);for(int i=0;i<keys.size();i++){Object v=r.get(keys.get(i));if("PART_CODE".equals(keys.get(i))&&r.get("PART_ID") instanceof Number part)v=PartColors.displayCode(db,part.longValue());var cell=row.createCell(i);if(v instanceof Number n)cell.setCellValue(n.doubleValue());else if(v instanceof Boolean b)cell.setCellValue(b);else if("SHIPMENT_PURPOSE".equals(keys.get(i)))cell.setCellValue(switch(Objects.toString(v,"SALE")){case "INTERNAL"->"Xuất nội bộ";case "CONSIGNMENT"->"Xuất cho khách nhận ký gửi";default->"Xuất cho khách";});else cell.setCellValue("VEHICLE_TYPE".equals(keys.get(i))?("COMMERCIAL".equals(v)?"Thương Mại":"Xe Đăng Kiểm"):v==null?"":Objects.toString(v));}}if(rows.isEmpty())sh.createRow(1).createCell(0).setCellValue("Chưa có dữ liệu");sh.createFreezePane(0,1);if(!rows.isEmpty())sh.setAutoFilter(new CellRangeAddress(0,rows.size(),0,keys.size()-1));}
 @GetMapping("/{entity}") @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public ResponseEntity<byte[]> export(@RequestHeader("Authorization") String t,@PathVariable String entity,@RequestParam(required=false) String ids,@RequestParam(defaultValue="false") boolean archived) throws IOException {var user=core.user(t,false);if(!entity.equals("all")&&!NAMES.containsKey(entity))throw new Api.Problem(404,"Không tìm thấy mục xuất Excel");Set<Long> selected=null;if(ids!=null){if(entity.equals("all"))throw new Api.Problem(400,"Chọn dòng trong từng mục để xuất Excel");selected=new TreeSet<>();try{String[] values=ids.split(",",-1);if(values.length<1||values.length>1000)throw new NumberFormatException();for(String value:values){long id=Long.parseLong(value);if(id<=0||!selected.add(id))throw new NumberFormatException();}}catch(NumberFormatException e){throw new Api.Problem(400,"Danh sách dòng xuất không hợp lệ");}}if(archived){if(!entity.equals("audit"))throw new Api.Problem(400,"Danh sách đã ẩn chỉ dành cho nhật ký");core.admin(t);}try(var book=new XSSFWorkbook();var bytes=new ByteArrayOutputStream()){var entities=entity.equals("all")?List.of("parts","suppliers","stock","models","documents","bom","production","vehicles","receipts","shipments","reports","audit"):List.of(entity);for(String e:entities){if(AccountKinds.get(db,user.id()).equals("STORE")&&Set.of("bom","production").contains(e))continue;List<Map<String,Object>> rows;if(e.equals("receipts"))rows=db.queryForList("SELECT r.*,COUNT(v.id) quantity FROM vehicle_receipts r LEFT JOIN vehicles v ON v.receipt_id=r.id WHERE r.deleted=FALSE GROUP BY r.id");else if(e.equals("reports")){@SuppressWarnings("unchecked") var result=(List<Map<String,Object>>)core.reports(t);rows=result;}else if(e.equals("audit")&&archived)rows=db.queryForList("SELECT a.id,a.user_id,a.action,a.entity,a.entity_id,a.details,a.user_note,a.archived,a.created_at,u.display_name actor FROM audit_log a JOIN app_users u ON u.id=a.user_id WHERE a.archived=TRUE ORDER BY a.id DESC LIMIT 500");else rows=core.list(e,t);if(selected!=null){var chosen=new ArrayList<Map<String,Object>>();for(var row:rows)if(selected.contains(((Number)row.get("ID")).longValue()))chosen.add(row);if(chosen.size()!=selected.size())throw new Api.Problem(409,"Dữ liệu đã thay đổi. Anh làm mới danh sách và chọn lại.");rows=chosen;}sheet(book,NAMES.get(e),rows);String sql=switch(e){case "documents"->"SELECT d.code,l.*,p.code part_code,p.name part_name FROM stock_document_lines l JOIN stock_documents d ON d.id=l.document_id JOIN parts p ON p.id=l.part_id WHERE d.deleted=FALSE";case "bom"->"SELECT m.name model,b.version,l.*,p.code part_code,p.name part_name FROM bom_lines l JOIN bom_versions b ON b.id=l.bom_id JOIN vehicle_models m ON m.id=b.model_id JOIN parts p ON p.id=l.part_id WHERE b.deleted=FALSE";case "production"->"SELECT o.code,l.*,p.code part_code,p.name part_name FROM production_materials l JOIN production_orders o ON o.id=l.order_id JOIN parts p ON p.id=l.part_id WHERE o.deleted=FALSE";case "receipts"->"SELECT r.code receipt_code,m.name model,v.color,v.vehicle_type,v.frame_number,v.motor_number,v.status FROM vehicle_receipts r JOIN vehicles v ON v.receipt_id=r.id JOIN vehicle_models m ON m.id=v.model_id WHERE r.deleted=FALSE";case "shipments"->"SELECT s.code shipment_code,s.shipment_purpose,s.customer,s.shipment_date,s.phone,s.address,s.reason,s.accessories,l.requested_quantity,1 actual_quantity,l.unit_price,l.unit_price amount,l.item_code,l.description,m.name model,v.color,v.frame_number,v.motor_number,v.status FROM vehicle_shipments s JOIN vehicle_shipment_lines l ON l.shipment_id=s.id JOIN vehicles v ON v.id=l.vehicle_id JOIN vehicle_models m ON m.id=v.model_id WHERE s.deleted=FALSE";default->null;};if(sql!=null){if(selected==null)sheet(book,"Chi tiết "+NAMES.get(e),db.queryForList(sql));else{String alias=switch(e){case "documents"->"d";case "bom"->"b";case "production"->"o";case "receipts"->"r";case "shipments"->"s";default->throw new IllegalStateException();};sheet(book,"Chi tiết "+NAMES.get(e),db.queryForList(sql+" AND "+alias+".id IN ("+String.join(",",Collections.nCopies(selected.size(),"?"))+")",selected.toArray()));}}}if(entity.equals("all")&&user.role().equals("ADMIN"))sheet(book,NAMES.get("users"),core.list("users",t));sheet(book,"Thông tin",List.of(Map.of("Công ty","Công ty cổ phần sản xuất và kinh doanh Vĩnh Khang","Ngày xuất",java.time.LocalDateTime.now().toString(),"Nội dung","Bản sao dữ liệu để quản lý bên ngoài; chỉnh Excel không thay đổi dữ liệu app")));book.write(bytes);return ResponseEntity.ok().header("Content-Disposition","attachment; filename=vinh-khang.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(bytes.toByteArray());}}
}
